    def rancnf_georesiliency(self, action, dist_names=None, working_sets=None, parameters=None,
                             verbose=True, ignore_errors=False, timeout=7200):
        """
        Perform the operation depending on the action parameter:
            - ``RANCNF_GeoResiliency_Disable`` for ``disable`` action
            - ``RANCNF_GeoResiliency_Enable`` for ``enable`` action
            - ``RANCNF_GeoResiliency_Synchronize`` for ``synchronize`` action

        Disabling or enabling a list of VCU, or synchronize a list of secondary VCUs.

        :param str action: Allowed values: ``disable``, ``enable`` or ``synchronize``
        :param str|list(str) dist_names: Specifies the scope of the operation, e.g., ``PLMN-PLMN/MRBTS-100``.
            At least one of the arguments ``dist_names`` or ``working_sets`` must be defined
        :param str|list(str) working_sets: Specifies the scope of the operation as defined in the working set.
            At least one of the arguments ``dist_names`` or ``working_sets`` must be defined
        :param dict parameters: Optional parameters not exposed at the method level but accepted by CLI, e.g.:
            {
                '-schedule': '<output from prepare_schedule method>'
            }
        :param bool verbose: If True, returns more detailed output from executed operation
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails
        :param int timeout: Timeout for executing operation
        :return: Operation output
        """
        supported_actions = {
            'disable': 'RANCNF_GeoResiliency_Disable',
            'enable': 'RANCNF_GeoResiliency_Enable',
            'synchronize': 'RANCNF_GeoResiliency_Synchronize'
        }
        if action not in supported_actions:
            raise ValueError(f"'{action}' is not a valid action")
        if not (dist_names or working_sets):
            raise ValueError('At least one of the parameters dist_names or working_sets must be defined.')

        parameters = parameters or {}
        parameters.update({'-op': supported_actions[action],
                           '-DN': dist_names,
                           '-WS': working_sets})
        return self._execute_operation(parameters, verbose, ignore_errors, timeout)

    def import_k8s_resource_plan(self, cloud_dist_name, plan_name, input_file_chooser=None,
                                 cleanup=True, verbose=True, ignore_errors=False, timeout=7200):
        """
        Perform the ``K8s_Resource_Import_Plan`` operation.

        This operation allows user to create new plan based on file with RANCNF Object from K8s.

        :param str cloud_dist_name: DN of the CLOUD under which Managed Objects should be created
        :param str plan_name: The name of plan to create
        :param str input_file_chooser: The input file,
            e.g., ``/var/opt/oss/global/racops/import/<k8sInput.yaml or k8sInput.json>``
            A local file path is supported. In this case, the file is uploaded to NetAct before executing the operation.
            If local file does not exist, it is assumed that the file is already present in NetAct under given path.
        :param bool cleanup: Specifies if the uploaded file has to be removed from NetAct upon completion
        :param bool verbose: If ``True``, returns more detailed output from executed operation
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails
        :param int timeout: Timeout for executing operation
        :return: Operation output
        """
        if input_file_chooser and os.path.exists(input_file_chooser):
            file_name = os.path.basename(input_file_chooser)
            local_dir = os.path.dirname(input_file_chooser)
            input_file_chooser = os.path.join(self.IMPORT_DIR, file_name)
        else:
            file_name = None
            local_dir = None
        parameters = {'-op': 'K8s_Resource_Import_Plan',
                      '-cloudDn': cloud_dist_name,
                      '-planName': plan_name,
                      '-inputFileChooser': input_file_chooser}
        return self._put_file_and_execute_operation(
            parameters, file_name, local_dir, self.IMPORT_DIR,
            cleanup, verbose, ignore_errors, timeout
        )
